/// Resolve a builtin alias spelling to its schema row.
pub(crate) fn builtin_exception_alias(name: &str) -> Option<&'static BuiltinExceptionSpec> {
    match name {
        "EnvironmentError" => Some(&BUILTIN_EXCEPTION_SPECS[79]),
        "IOError" => Some(&BUILTIN_EXCEPTION_SPECS[80]),
        "WindowsError" => Some(&BUILTIN_EXCEPTION_SPECS[81]),
        _ => None,
    }
}
